-- MyNclex bank gap-fill batch: Maternity / antenatal and pregnancy care
-- Batch: gapfill-20260728   Item block: 510001-510055 (55 items)
-- Subject: Maternity. Topics: dating and Naegele rule, weight gain, fundal height,
-- signs of pregnancy, visit schedule, anaemia, common discomforts, danger signs,
-- gestational diabetes, hypertensive disorders, antepartum haemorrhage, ectopic,
-- hyperemesis, molar pregnancy, Rh alloimmunisation, antenatal screening,
-- nutrition and immunisation.
-- Types: 25 MCQ, 14 SATA, 5 SELECT_N, 4 MATRIX, 3 MATRIX_MR, 2 CLOZE, 1 TF, 1 DRAG_ORDER.

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_510001', 'MCQ', 'A client attending the antenatal clinic reports that the first day of her last menstrual period was 12 August. Her cycles are regular and 28 days long. Using Naegele''s rule, which estimated date of delivery should the nurse calculate?',
 'Naegele''s rule adds 7 days to the first day of the last menstrual period, then subtracts 3 months and adds one year: 12 August plus 7 days is 19 August, and 3 months back gives 19 May of the following year. The rule assumes a regular 28-day cycle with ovulation on about day 14, so it is only reliable when cycles are regular and the date of the last period is certain. An estimated date of delivery is a mid-point, not a deadline: only about 4 in 100 clients give birth on that exact date.',
 '{"options": [{"id": "A", "text": "12 May"}, {"id": "B", "text": "19 May"}, {"id": "C", "text": "5 May"}, {"id": "D", "text": "19 June"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. This omits the addition of 7 days to the first day of the last menstrual period.", "B": "Correct. Adding 7 days to 12 August gives 19 August, and subtracting 3 months gives 19 May of the next year.", "C": "Incorrect. This subtracts 7 days instead of adding them; the rule adds 7 days to the first day of the last period.", "D": "Incorrect. This subtracts only 2 months; Naegele''s rule subtracts 3 months."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Naegele rule', 'Estimated date of delivery', 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510002', 'MCQ', 'A client attending for her first antenatal visit reports irregular cycles of 35 to 42 days and is not certain when her last menstrual period began. Which action by the nurse is BEST?',
 'Naegele''s rule assumes a 28-day cycle; when cycles are long or irregular, ovulation occurs later than day 14 and dating from the last menstrual period overestimates gestational age. Ultrasound measurement of the crown-rump length before 14 weeks is accurate to within about 5 days and is the recommended method when the last menstrual period is uncertain. Accurate dating matters because it determines the timing of screening tests and the definition of preterm and post-term birth.',
 '{"options": [{"id": "A", "text": "Date the pregnancy from the day the client first feels fetal movement"}, {"id": "B", "text": "Wait until the fundus can be palpated at the umbilicus and date the pregnancy from that visit"}, {"id": "C", "text": "Arrange an early ultrasound scan so that the pregnancy can be dated by crown-rump length"}, {"id": "D", "text": "Apply Naegele''s rule to the client''s best estimate of her last menstrual period"}]}'::jsonb,
 '{"answer": "C", "feedback": {"A": "Incorrect. Quickening varies widely between clients and between pregnancies and is far too imprecise for dating.", "B": "Incorrect. Waiting until 20 weeks delays screening decisions, and fundal height is affected by maternal build, fibroids and liquor volume.", "C": "Correct. First-trimester ultrasound is the most accurate method of dating when the last menstrual period is unreliable.", "D": "Incorrect. A guessed date combined with a rule that assumes a 28-day cycle produces an unreliable estimated date of delivery."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Pregnancy dating', 'Uncertain last menstrual period', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510003', 'MCQ', 'A client with a pre-pregnancy body mass index of 22 kg/m2 asks the nurse how much weight she should expect to gain during the pregnancy. Which total gain should the nurse describe as expected?',
 'Recommended total gain is based on pre-pregnancy body mass index: about 12.5 to 18 kg if underweight, 11.5 to 16 kg if the body mass index is normal, 7 to 11.5 kg if overweight and 5 to 9 kg if obese. Most of the gain occurs after the first trimester, at roughly 0.4 kg each week. Framing the target as a range, rather than a single number, keeps the conversation supportive and reduces the risk of restrictive dieting in pregnancy.',
 '{"options": [{"id": "A", "text": "5 to 9 kg"}, {"id": "B", "text": "7 to 11.5 kg"}, {"id": "C", "text": "18 to 23 kg"}, {"id": "D", "text": "11.5 to 16 kg"}]}'::jsonb,
 '{"answer": "D", "feedback": {"A": "Incorrect. This is the range recommended for a client who is obese before pregnancy.", "B": "Incorrect. This is the range recommended for a client who is overweight before pregnancy.", "C": "Incorrect. This exceeds every recommended range and increases the risk of macrosomia and postnatal weight retention.", "D": "Correct. A client whose body mass index is in the normal range is advised to gain about 11.5 to 16 kg in total."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Weight gain in pregnancy', 'Recommended total gain', 'Very easy', 'CURATOR_LABEL', 'Remember', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510004', 'MCQ', 'A client at 32 weeks of gestation has gained 2.5 kg in the week since her last visit. She says her rings no longer fit and that she has had a headache since waking. Which action is the PRIORITY?',
 'A gain of more than about 1 kg in a week in the third trimester reflects fluid retention rather than tissue growth. Combined with facial or digital oedema and a headache, it points towards pre-eclampsia, and the two pieces of data that establish the diagnosis are the blood pressure and the urine protein. Reassurance, dietary advice or a dietitian referral all delay the assessment that determines whether this client needs same-day obstetric review.',
 '{"options": [{"id": "A", "text": "Measure the blood pressure and test the urine for protein"}, {"id": "B", "text": "Advise the client to reduce her salt intake and rest with her feet raised"}, {"id": "C", "text": "Reassure the client that swelling is a normal finding in late pregnancy"}, {"id": "D", "text": "Refer the client to the dietitian to review her food intake"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Rapid weight gain with oedema and headache suggests pre-eclampsia, and blood pressure plus urine protein are the data needed to act.", "B": "Incorrect. Salt restriction has no role in preventing or treating pre-eclampsia and delays assessment.", "C": "Incorrect. Dependent ankle oedema is common, but sudden weight gain with facial oedema and headache is not a normal finding.", "D": "Incorrect. The gain is fluid, not excess dietary intake, so a dietitian review does not address the immediate concern."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Multisystem',
 'Weight gain in pregnancy', 'Sudden weight gain', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510005', 'MCQ', 'At a routine visit, a client at 28 weeks of gestation has a symphysis-fundal height of 24 cm. Her two previous measurements followed the expected curve. Which action should the nurse take next?',
 'From about 24 weeks the symphysis-fundal height in centimetres approximates the gestational age in weeks, within about 2 cm. A measurement 3 cm or more below the expected value, or a flattening of the plotted curve, suggests fetal growth restriction, oligohydramnios or inaccurate dates, and ultrasound assessment of growth and liquor volume is the investigation that distinguishes between them. Deferring the measurement to the next routine visit risks missing a growth-restricted fetus at the point where surveillance would change the outcome.',
 '{"options": [{"id": "A", "text": "Advise the client to increase her protein intake and re-measure in one week"}, {"id": "B", "text": "Refer the client for an ultrasound scan of fetal growth and liquor volume"}, {"id": "C", "text": "Record the measurement and repeat it at the next routine visit in 4 weeks"}, {"id": "D", "text": "Reassure the client that fundal height is unreliable after 24 weeks"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Maternal protein intake does not correct placental insufficiency, and the delay leaves the fetus unmonitored.", "B": "Correct. A lag of 3 cm or more with a flattening growth curve requires ultrasound assessment of growth and liquor volume.", "C": "Incorrect. Waiting 4 weeks delays detection of a growth-restricted fetus, when surveillance and timing of birth may need to change.", "D": "Incorrect. After 24 weeks fundal height correlates well enough with gestation to be used as a screening measurement."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Fundal height', 'Size less than dates', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510006', 'MCQ', 'A client at 10 weeks of gestation has a haemoglobin of 9.8 g/dL. Which interpretation by the nurse is correct?',
 'Anaemia in pregnancy is defined as a haemoglobin below 11 g/dL in the first and third trimesters and below 10.5 g/dL in the second, because plasma volume expands faster than red cell mass and dilutes the haemoglobin. A first-trimester value of 9.8 g/dL is below the threshold at a point when haemodilution is still minimal, so it represents true anaemia and warrants evaluation with ferritin and treatment. Untreated anaemia is associated with preterm birth, low birth weight and reduced tolerance of blood loss at delivery.',
 '{"options": [{"id": "A", "text": "The value is expected because plasma volume peaks during the first trimester"}, {"id": "B", "text": "The value should simply be rechecked at 36 weeks with the routine bloods"}, {"id": "C", "text": "The value is below the first-trimester threshold and requires evaluation for anaemia"}, {"id": "D", "text": "The value reflects the normal haemodilution of pregnancy and needs no action"}]}'::jsonb,
 '{"answer": "C", "feedback": {"A": "Incorrect. Plasma volume expands progressively and peaks at about 28 to 34 weeks, not in the first trimester.", "B": "Incorrect. Delaying treatment for six months leaves the client anaemic through the period of greatest fetal iron demand.", "C": "Correct. A haemoglobin below 11 g/dL in the first trimester is below the threshold and requires evaluation.", "D": "Incorrect. Haemodilution is minimal this early and does not account for a value of 9.8 g/dL."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Multisystem',
 'Anaemia in pregnancy', 'Haemoglobin thresholds by trimester', 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510007', 'MCQ', 'A woman who is planning to conceive asks the nurse when she should start taking folic acid. Which response by the nurse is correct?',
 'The neural tube closes by about 28 days after conception, which is often before a pregnancy is recognised, so folic acid taken only after a positive test comes too late to give full protection. The standard advice is 400 micrograms daily from at least one month before conception until the end of the twelfth week. Supplementation reduces the risk of neural tube defects such as spina bifida and anencephaly by around 70 per cent.',
 '{"options": [{"id": "A", "text": "Start as soon as the pregnancy test is positive"}, {"id": "B", "text": "Start at the booking visit, which is usually at about 10 weeks"}, {"id": "C", "text": "Start in the second trimester, when fetal growth is fastest"}, {"id": "D", "text": "Start at least one month before conceiving and continue until the end of the twelfth week"}]}'::jsonb,
 '{"answer": "D", "feedback": {"A": "Incorrect. A positive test usually comes after the neural tube has begun to close, so protection is incomplete.", "B": "Incorrect. By 10 weeks the neural tube has long closed and the protective window has passed.", "C": "Incorrect. Folic acid prevents neural tube defects in early embryonic life, not in the second trimester.", "D": "Correct. Cover is needed before conception because the neural tube closes by about 28 days after conception."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Maternity', 'Reproductive',
 'Folic acid', 'Preconception supplementation', 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510008', 'MCQ', 'A client whose first baby was born with spina bifida is planning another pregnancy. Which folic acid dose should the nurse expect to be prescribed?',
 'A previous pregnancy affected by a neural tube defect raises the recurrence risk substantially, and high-dose folic acid, 5 mg daily in the United Kingdom and 4 mg daily in the United States, is prescribed from before conception until the end of the first trimester. The same high dose is used for clients with diabetes, those taking anti-epileptic medicines, those with sickle cell disease and those with a body mass index of 30 kg/m2 or more. The routine 400 microgram dose is intended for clients without these risk factors.',
 '{"options": [{"id": "A", "text": "5 mg daily, started before conception"}, {"id": "B", "text": "400 micrograms daily, started before conception"}, {"id": "C", "text": "400 micrograms on alternate days throughout pregnancy"}, {"id": "D", "text": "1 mg daily, started in the second trimester"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. A previous neural tube defect is an indication for high-dose folic acid from before conception.", "B": "Incorrect. The routine dose is intended for clients without risk factors and is insufficient after an affected pregnancy.", "C": "Incorrect. Alternate-day dosing provides less than the routine daily dose and no additional protection.", "D": "Incorrect. Both the dose and the timing are wrong; the protective window closes early in the first trimester."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Maternity', 'Reproductive',
 'Folic acid', 'High-dose indication', 'Hard', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510009', 'MCQ', 'A client at 8 weeks of gestation tells the nurse that she feels sick and vomits most mornings. Which advice should the nurse give?',
 'Nausea and vomiting of pregnancy is worst when the stomach is empty and blood glucose is low, which is why it typically peaks on waking. Eating a dry carbohydrate snack before rising, then taking small frequent low-fat meals and keeping fluids between rather than with meals, addresses the mechanism. The symptom usually settles by about 16 weeks; persistent vomiting with weight loss and ketonuria is hyperemesis gravidarum and needs medical assessment.',
 '{"options": [{"id": "A", "text": "Eat a hot, fatty breakfast to line the stomach"}, {"id": "B", "text": "Eat a dry biscuit or cracker before getting out of bed and take small, frequent meals"}, {"id": "C", "text": "Drink a large glass of water with every meal to dilute the stomach acid"}, {"id": "D", "text": "Avoid all food until the nausea has settled later in the day"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Fatty foods delay gastric emptying and typically aggravate the nausea.", "B": "Correct. A dry carbohydrate snack before rising and small frequent meals prevent the empty stomach that triggers the nausea.", "C": "Incorrect. Large volumes of fluid with meals distend the stomach and worsen nausea; fluids are better taken between meals.", "D": "Incorrect. Fasting lowers blood glucose further and makes the nausea worse, and risks dehydration."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Nausea and vomiting of pregnancy', 'Self-care advice', 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510010', 'MCQ', 'A client at 9 weeks of gestation says she is passing urine very often and has started drinking much less so that she can sleep through the night. Which response by the nurse is correct?',
 'Urinary frequency in the first trimester is caused by the enlarging uterus pressing on the bladder and by increased renal blood flow; it settles as the uterus rises out of the pelvis and returns in the third trimester when the presenting part engages. Restricting fluid does not reduce the pressure on the bladder and increases the risk of dehydration, constipation and urinary tract infection. The safe adjustment is to maintain intake through the day and reduce it only in the hours immediately before bed.',
 '{"options": [{"id": "A", "text": "Frequency at this stage nearly always means infection, so antibiotics will be needed"}, {"id": "B", "text": "Limit total fluid intake to one litre a day until the frequency settles"}, {"id": "C", "text": "Keep drinking normally during the day and cut back only in the last hours before bed"}, {"id": "D", "text": "Restricting fluids through the day is a sensible way to manage frequency in pregnancy"}]}'::jsonb,
 '{"answer": "C", "feedback": {"A": "Incorrect. Frequency alone is an expected finding; burning, urgency, haematuria or flank pain would suggest infection.", "B": "Incorrect. One litre a day is inadequate in pregnancy, when plasma volume and renal workload are both increased.", "C": "Correct. Intake is maintained and only the evening portion is shifted, which protects hydration and sleep.", "D": "Incorrect. Fluid restriction increases the risk of dehydration, constipation and urinary tract infection without relieving the pressure."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Urinary frequency', 'First trimester discomfort', 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_510011', 'MCQ', 'A client at 30 weeks of gestation reports low back pain that is worst by the end of the day. Which measure should the nurse teach?',
 'Back pain in later pregnancy comes from the forward shift in the centre of gravity, the resulting lumbar lordosis and the softening of pelvic ligaments by relaxin. Pelvic tilt exercises strengthen the abdominal muscles that support the lumbar spine, and squatting to lift with a straight back protects it during everyday tasks. Bed rest deconditions the same muscles and adds thromboembolic risk, so activity is modified rather than stopped.',
 '{"options": [{"id": "A", "text": "Remain on bed rest for the rest of the pregnancy"}, {"id": "B", "text": "Sleep flat on the back with the legs straight"}, {"id": "C", "text": "Wear high-heeled shoes to correct the posture"}, {"id": "D", "text": "Perform pelvic tilt exercises, squat to lift, and wear low-heeled supportive shoes"}]}'::jsonb,
 '{"answer": "D", "feedback": {"A": "Incorrect. Bed rest weakens the supporting muscles and raises the risk of venous thromboembolism.", "B": "Incorrect. Lying flat in late pregnancy also risks aortocaval compression; a left lateral position with pillow support is preferred.", "C": "Incorrect. High heels increase lordosis and make the back pain worse.", "D": "Correct. Pelvic tilts, safe lifting and supportive footwear address the lordosis and ligament laxity that cause the pain."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Back pain in pregnancy', 'Body mechanics teaching', 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510012', 'MCQ', 'A client at 36 weeks of gestation reports breathlessness when she lies down at night. Her oxygen saturation is 98 per cent on air, her chest is clear and she has no chest pain or cough. Which explanation should the nurse give?',
 'The uterus elevates the diaphragm by about 4 cm in late pregnancy, reducing residual volume and producing breathlessness that is worse when lying flat. It eases when the presenting part descends into the pelvis, and sleeping propped up on pillows relieves it in the meantime. Breathlessness at rest with chest pain, cough, haemoptysis, fever or a fall in oxygen saturation is not physiological and must be reported.',
 '{"options": [{"id": "A", "text": "The uterus is pressing the diaphragm upwards; sleeping propped on pillows helps until the baby settles into the pelvis"}, {"id": "B", "text": "This is an early sign of heart failure and needs urgent cardiology review"}, {"id": "C", "text": "This is caused by anaemia and the iron dose should be doubled"}, {"id": "D", "text": "The client should stay on bed rest until the baby is born"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Diaphragmatic elevation explains the symptom, and it eases with upright positioning and after lightening.", "B": "Incorrect. A clear chest, normal saturation and absence of chest pain or orthopnoea at rest make heart failure unlikely.", "C": "Incorrect. Doubling iron without a haemoglobin result is unsafe and does not explain positional breathlessness.", "D": "Incorrect. Bed rest does not relieve diaphragmatic pressure and increases thromboembolic risk."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Dyspnoea in pregnancy', 'Third trimester discomfort', 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510013', 'MCQ', 'During an antenatal examination, a client at 32 weeks of gestation who is lying flat on her back becomes pale, dizzy and nauseated. Her blood pressure is 88/50 mmHg. Which action should the nurse take FIRST?',
 'In supine hypotensive syndrome the gravid uterus compresses the inferior vena cava and aorta, venous return falls and cardiac output drops, reducing perfusion of both the client and the placenta. Turning the client onto her side, or wedging one hip, lifts the uterus off the great vessels and reverses the problem within moments, which is why it precedes oxygen, fluids or notification. If symptoms persist after repositioning, other causes of hypotension must be considered.',
 '{"options": [{"id": "A", "text": "Raise the foot of the couch and give a fluid bolus"}, {"id": "B", "text": "Turn the client onto her left side"}, {"id": "C", "text": "Start oxygen at 10 litres per minute by face mask"}, {"id": "D", "text": "Notify the obstetrician of the blood pressure"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. A fluid bolus treats hypovolaemia; this client is not hypovolaemic, and the uterus still compresses the vena cava.", "B": "Correct. Lateral positioning relieves aortocaval compression immediately and restores venous return.", "C": "Incorrect. Oxygen does not correct the mechanical obstruction to venous return that is causing the hypotension.", "D": "Incorrect. Notification is appropriate only after the simple corrective action has been taken."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Supine hypotensive syndrome', 'Immediate positioning', 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510014', 'MCQ', 'A nurse in the antenatal clinic has four telephone messages waiting. Which client should the nurse call back FIRST?',
 'Telephone triage ranks calls by the likelihood of harm before the next contact. A marked change in fetal movement pattern may be the only warning of fetal hypoxia and requires same-day assessment with cardiotocography, so it outranks calls about expected discomforts. Thick white non-irritant discharge, first-trimester nausea and end-of-day ankle oedema are all normal findings that can be dealt with later in the list.',
 '{"options": [{"id": "A", "text": "A client at 12 weeks reporting nausea every morning"}, {"id": "B", "text": "A client at 36 weeks reporting ankle swelling at the end of the day"}, {"id": "C", "text": "A client at 28 weeks who has felt no fetal movement since yesterday morning"}, {"id": "D", "text": "A client at 34 weeks reporting a thick white vaginal discharge without itching"}]}'::jsonb,
 '{"answer": "C", "feedback": {"A": "Incorrect. Nausea at 12 weeks is expected and, without weight loss or ketonuria, is not urgent.", "B": "Incorrect. Dependent ankle oedema that appears by the end of the day is a common late-pregnancy finding.", "C": "Correct. Absent or markedly reduced fetal movement may signal fetal compromise and needs same-day assessment.", "D": "Incorrect. Non-irritant white discharge is physiological leucorrhoea and can be addressed later."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Maternity', 'Multisystem',
 'Antenatal telephone triage', 'Priority call-back', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510015', 'MCQ', 'At her booking visit a client has a body mass index of 33 kg/m2 and reports that her mother has type 2 diabetes. When should the nurse expect glucose tolerance testing to be arranged?',
 'All clients are offered screening for gestational diabetes at 24 to 28 weeks, when placental hormones produce peak insulin resistance. Clients with risk factors such as a body mass index of 30 kg/m2 or more, previous gestational diabetes, a previous macrosomic baby, a first-degree relative with diabetes or a high-risk ethnic background are tested early as well, because undiagnosed pre-existing diabetes carries a risk of congenital anomaly. An early negative result does not remove the need for the routine test later.',
 '{"options": [{"id": "A", "text": "Only once, at 24 to 28 weeks, as for every other client"}, {"id": "B", "text": "At 36 weeks, when insulin resistance is at its greatest"}, {"id": "C", "text": "Only if glycosuria is detected on routine urinalysis"}, {"id": "D", "text": "At booking or in early pregnancy, and again at 24 to 28 weeks if the first result is normal"}]}'::jsonb,
 '{"answer": "D", "feedback": {"A": "Incorrect. Waiting until 24 weeks in a client with risk factors may miss pre-existing diabetes.", "B": "Incorrect. Testing at 36 weeks leaves too little time for treatment to influence fetal growth.", "C": "Incorrect. Glycosuria is an insensitive and non-specific screen and is not used to decide who is tested.", "D": "Correct. Risk factors trigger early testing, and a normal early result is followed by routine testing at 24 to 28 weeks."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Multisystem',
 'Gestational diabetes', 'Screening schedule', 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510016', 'MCQ', 'A client at 26 weeks of gestation has just been diagnosed with gestational diabetes. Which approach should the nurse describe as the first-line management?',
 'Most clients with gestational diabetes reach target glucose levels with dietary change, distributed carbohydrate intake, regular moderate activity and self-monitoring of blood glucose. Pharmacological treatment is added only when targets are not met after one to two weeks of this approach, or when fetal macrosomia is already present. Weight-reduction diets are not used in pregnancy because they risk ketosis and inadequate fetal nutrition.',
 '{"options": [{"id": "A", "text": "Dietary modification, regular physical activity and self-monitoring of blood glucose"}, {"id": "B", "text": "Immediate commencement of insulin at diagnosis"}, {"id": "C", "text": "A weight-reduction diet of 1200 kcal per day"}, {"id": "D", "text": "Metformin combined with insulin from the day of diagnosis"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Diet, activity and monitoring control the majority of cases and are the first-line approach.", "B": "Incorrect. Insulin is added when lifestyle measures fail to meet targets, not automatically at diagnosis.", "C": "Incorrect. Energy restriction of this degree risks ketosis and compromises fetal growth.", "D": "Incorrect. Combination therapy from diagnosis is not indicated and exposes the client to unnecessary treatment."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Multisystem',
 'Gestational diabetes', 'First-line management', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510017', 'MCQ', 'A client with gestational diabetes has been started on insulin. Which statement by the client indicates that teaching has been effective?',
 'Insulin is the reference treatment in pregnancy because the molecule does not cross the placenta, so it treats the client without directly exposing the fetus. Requirements rise as placental hormones increase insulin resistance, so doses are titrated upward rather than minimised. Skipping meals or omitting doses produces swings in glucose and risks ketosis, which is why monitoring fasting and one-hour post-meal values and bringing the record to each visit is the behaviour that shows understanding.',
 '{"options": [{"id": "A", "text": "\"Insulin crosses to the baby, so I will take the smallest dose I can manage.\""}, {"id": "B", "text": "\"I will check my glucose fasting and one hour after meals and bring the record to each visit.\""}, {"id": "C", "text": "\"If my glucose is high I will skip the next meal to bring it down.\""}, {"id": "D", "text": "\"I can leave out the insulin on days when I do not eat much.\""}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Insulin does not cross the placenta, and deliberate under-dosing leaves the fetus exposed to maternal hyperglycaemia.", "B": "Correct. Fasting and one-hour post-meal monitoring with a shared record is exactly how doses are titrated in pregnancy.", "C": "Incorrect. Skipping meals causes swings in glucose and ketosis and does not correct hyperglycaemia safely.", "D": "Incorrect. Omitting insulin on low-intake days risks ketoacidosis; doses are adjusted, not stopped."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Maternity', 'Multisystem',
 'Insulin in pregnancy', 'Self-monitoring teaching', 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510018', 'MCQ', 'A client at 34 weeks of gestation has a blood pressure of 148/96 mmHg on two readings four hours apart and 2+ protein on urinalysis. Her booking blood pressure was 110/70 mmHg. Which action should the nurse take next?',
 'New hypertension after 20 weeks with proteinuria meets the definition of pre-eclampsia, a multisystem disorder that can progress quickly and unpredictably. The nurse contacts the obstetric team for same-day review and arranges the bloods that identify organ involvement: platelets, liver enzymes and creatinine, together with fetal assessment. Sending the client home on dietary advice or deferring review to the next routine visit leaves a deteriorating disorder unmonitored.',
 '{"options": [{"id": "A", "text": "Repeat the blood pressure at the next scheduled visit in four weeks"}, {"id": "B", "text": "Advise the client to rest at home and return only if a headache develops"}, {"id": "C", "text": "Contact the obstetric team for same-day assessment and arrange platelets, liver enzymes and creatinine"}, {"id": "D", "text": "Book a routine review in two weeks and advise a low-salt diet"}]}'::jsonb,
 '{"answer": "C", "feedback": {"A": "Incorrect. A four-week interval allows severe features to develop without monitoring.", "B": "Incorrect. Waiting for symptoms means acting only after the disorder has already progressed.", "C": "Correct. New hypertension with proteinuria after 20 weeks requires prompt obstetric review and blood tests for organ involvement.", "D": "Incorrect. Salt restriction does not treat pre-eclampsia, and a two-week delay is unsafe."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Maternity', 'Multisystem',
 'Pre-eclampsia', 'Initial obstetric referral', 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510019', 'MCQ', 'A client at 32 weeks of gestation is admitted with painless bright red vaginal bleeding, and ultrasound confirms placenta praevia. Which action is CONTRAINDICATED?',
 'In placenta praevia the placenta lies over or close to the internal cervical os, and a digital or speculum examination can disturb the placental edge and provoke torrential haemorrhage. Assessment therefore relies on ultrasound, external monitoring of the fetal heart, quantified blood loss and cross-matched blood. The general rule is that no vaginal examination is performed for antepartum bleeding until placenta praevia has been excluded by ultrasound.',
 '{"options": [{"id": "A", "text": "Applying continuous electronic fetal heart rate monitoring"}, {"id": "B", "text": "Weighing the perineal pads to quantify the blood loss"}, {"id": "C", "text": "Taking blood for group and cross-match"}, {"id": "D", "text": "Performing a digital vaginal examination"}]}'::jsonb,
 '{"answer": "D", "feedback": {"A": "Incorrect. External fetal monitoring is safe and is needed to assess fetal wellbeing.", "B": "Incorrect. Weighing pads is a safe and accurate way of quantifying ongoing loss.", "C": "Incorrect. Cross-matching is essential preparation in case transfusion becomes necessary.", "D": "Correct. Digital examination can disturb the low-lying placenta and cause catastrophic haemorrhage."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Maternity', 'Reproductive',
 'Placenta praevia', 'Contraindicated assessment', 'Medium', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510020', 'MCQ', 'A client at 36 weeks of gestation attends after a fall with sudden severe abdominal pain, a rigid tender uterus and dark red vaginal bleeding. Which action should the nurse take FIRST?',
 'These findings suggest abruptio placentae, in which the placenta separates before birth and part of the blood loss may be concealed behind it. Because the fetus loses its gas exchange surface immediately, the fetal heart rate is the earliest and most sensitive indicator of the degree of separation, so continuous monitoring is started at once while help is summoned. Vaginal examination and lying the client flat are unsafe, and analgesia would mask the picture without addressing the emergency.',
 '{"options": [{"id": "A", "text": "Apply continuous electronic fetal heart rate monitoring"}, {"id": "B", "text": "Give the prescribed analgesia for the abdominal pain"}, {"id": "C", "text": "Perform a digital vaginal examination to assess cervical dilatation"}, {"id": "D", "text": "Lay the client flat on her back so the uterus can be palpated"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Fetal heart rate changes are the earliest indicator of the degree of placental separation.", "B": "Incorrect. Analgesia masks a key sign and does nothing about the threat to the fetus.", "C": "Incorrect. Vaginal examination is withheld in antepartum haemorrhage until placenta praevia has been excluded.", "D": "Incorrect. The supine position causes aortocaval compression and further reduces placental perfusion."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Abruptio placentae', 'Immediate action', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_510021', 'MCQ', 'A client with 7 weeks of amenorrhoea attends with sudden left iliac fossa pain and pain at the tip of the right shoulder. She is pale and clammy, with a pulse of 124 beats per minute and a blood pressure of 84/48 mmHg. Which action is the PRIORITY?',
 'Shoulder-tip pain in early pregnancy comes from blood irritating the diaphragm, and with tachycardia and hypotension it indicates a ruptured ectopic pregnancy with intraperitoneal bleeding. Circulation is the immediate threat to life, so large-bore intravenous access, fluid resuscitation and cross-matched blood accompany urgent surgical referral. Confirmatory tests and analgesia matter, but they follow rather than replace resuscitation.',
 '{"options": [{"id": "A", "text": "Sit the client upright to relieve the shoulder pain"}, {"id": "B", "text": "Insert two large-bore intravenous cannulae, begin fluid resuscitation and arrange urgent surgical review"}, {"id": "C", "text": "Send a urine sample for a pregnancy test"}, {"id": "D", "text": "Give a strong analgesic and reassess the pain in 30 minutes"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Sitting upright does not treat the referred pain and may worsen cerebral perfusion in shock.", "B": "Correct. The client is in hypovolaemic shock from a probable ruptured ectopic pregnancy, so circulation is the priority.", "C": "Incorrect. Confirming the pregnancy does not address the shock and must not delay resuscitation.", "D": "Incorrect. Analgesia alone leaves the client bleeding into the abdomen."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Ectopic pregnancy', 'Ruptured ectopic', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510022', 'MCQ', 'A non-stress test on a client at 34 weeks of gestation shows no accelerations during 20 minutes of monitoring. Which action should the nurse take next?',
 'After 32 weeks a reactive tracing requires two accelerations of at least 15 beats per minute lasting at least 15 seconds within 20 minutes. The commonest reason for a non-reactive tracing is a fetal sleep cycle, which typically lasts 20 to 40 minutes, so the test is extended to 40 minutes with a snack, a change of position or vibroacoustic stimulation before it is called non-reactive. A tracing that remains non-reactive is then followed by a biophysical profile or contraction stress test rather than by immediate birth.',
 '{"options": [{"id": "A", "text": "Prepare the client immediately for caesarean birth"}, {"id": "B", "text": "Stop the test and repeat it in one week"}, {"id": "C", "text": "Offer a drink or snack, apply vibroacoustic stimulation and continue the tracing for a further 20 minutes"}, {"id": "D", "text": "Record the test as reactive and discharge the client home"}]}'::jsonb,
 '{"answer": "C", "feedback": {"A": "Incorrect. A single non-reactive tracing requires further testing, not immediate birth.", "B": "Incorrect. A week-long delay leaves a possibly compromised fetus unassessed.", "C": "Correct. Extending the test with stimulation distinguishes a fetal sleep cycle from genuine non-reactivity.", "D": "Incorrect. A tracing without accelerations does not meet the criteria for reactivity."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Non-stress test', 'Non-reactive tracing', 'Hard', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510023', 'MCQ', 'A client at 36 weeks of gestation has a biophysical profile score of 4 out of 10. Which action should the nurse anticipate?',
 'The biophysical profile scores fetal breathing, gross body movement, tone, amniotic fluid volume and the non-stress test, giving 0 or 2 points each. A score of 8 to 10 is reassuring, 6 is equivocal and prompts repeat testing within 24 hours, and 4 or less indicates probable fetal hypoxia. At 36 weeks a score of 4 usually means arranging birth after obstetric review rather than continued surveillance.',
 '{"options": [{"id": "A", "text": "Repeating the profile in one week"}, {"id": "B", "text": "Reassuring the client that the result is within normal limits"}, {"id": "C", "text": "Sending the client home with a repeat test booked in 24 hours"}, {"id": "D", "text": "Preparing the client for birth after informing the obstetric team"}]}'::jsonb,
 '{"answer": "D", "feedback": {"A": "Incorrect. A week of further surveillance is unsafe with an abnormal score.", "B": "Incorrect. Only a score of 8 to 10 with normal fluid is reassuring.", "C": "Incorrect. Repeat testing in 24 hours applies to an equivocal score of 6, not to a score of 4.", "D": "Correct. A score of 4 or less indicates probable fetal hypoxia, and at 36 weeks birth is generally arranged."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Biophysical profile', 'Score interpretation', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510024', 'MCQ', 'A client whose vaginal and rectal swab at 36 weeks was positive for group B streptococcus asks why she has not been given antibiotics now. Which response by the nurse is correct?',
 'Group B streptococcus colonises the genital tract intermittently, so antibiotics given in the antenatal period do not prevent recolonisation before birth. Protection for the newborn comes from intravenous penicillin, or a suitable alternative if the client is allergic, given once labour starts or the membranes rupture, ideally at least four hours before birth. Treating the newborn afterwards is a response to infection rather than prevention of it.',
 '{"options": [{"id": "A", "text": "\"Antibiotics are given through a drip once labour starts or the waters break, because treating now would not stop the bacteria returning.\""}, {"id": "B", "text": "\"You will take a week-long course of tablets before the birth.\""}, {"id": "C", "text": "\"The swab result only matters if you develop a fever.\""}, {"id": "D", "text": "\"Antibiotics are given to the baby after the birth rather than to you.\""}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Intrapartum intravenous antibiotics, ideally at least four hours before birth, are what protect the newborn.", "B": "Incorrect. Antenatal oral treatment does not prevent recolonisation before labour.", "C": "Incorrect. A positive swab dictates intrapartum prophylaxis whether or not fever develops.", "D": "Incorrect. Giving antibiotics only after birth treats established infection rather than preventing it."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Maternity', 'Reproductive',
 'Group B streptococcus', 'Intrapartum prophylaxis', 'Medium', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MCQ_510025', 'MCQ', 'A client at 9 weeks of gestation with a planned and wanted pregnancy says quietly that some days she wishes she were not pregnant. Which response by the nurse is BEST?',
 'Ambivalence is a normal psychological task of the first trimester, when the pregnancy is felt physically but the baby is not yet real to the client. Naming the feeling as common and inviting the client to say more keeps the conversation open and allows genuine distress to surface. Reproach, false reassurance or an immediate referral all close the exchange and imply that the feeling itself is unacceptable.',
 '{"options": [{"id": "A", "text": "\"Most women feel excited at this stage; it will pass once you feel the baby move.\""}, {"id": "B", "text": "\"Mixed feelings are common early in pregnancy. Tell me more about what has been on your mind.\""}, {"id": "C", "text": "\"You should not say that when you tried for so long to conceive.\""}, {"id": "D", "text": "\"I will refer you to the mental health team straight away.\""}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Comparison with others and false reassurance dismiss the client and close the conversation.", "B": "Correct. Normalising ambivalence and inviting elaboration is therapeutic and keeps assessment open.", "C": "Incorrect. This is a reproach; it shames the client and stops disclosure.", "D": "Incorrect. An immediate referral treats a normal developmental feeling as pathology without further assessment."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Maternity', 'Reproductive',
 'Maternal role attainment', 'First trimester ambivalence', 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510026', 'SATA', 'A client at 30 weeks of gestation has a symphysis-fundal height of 35 cm. Which explanations should the nurse consider? Select all that apply.',
 'A fundal height more than 3 cm greater than the gestational age suggests that the uterine contents are larger than expected or that the dates are wrong. Multiple pregnancy, polyhydramnios, fetal macrosomia associated with diabetes and underestimated gestation are the common explanations, and ultrasound distinguishes between them. Oligohydramnios and fetal growth restriction produce the opposite finding, a fundal height smaller than expected.',
 '{"options": [{"id": "A", "text": "Fetal macrosomia associated with poorly controlled diabetes"}, {"id": "B", "text": "Gestation more advanced than the recorded dates"}, {"id": "C", "text": "Fetal growth restriction"}, {"id": "D", "text": "Multiple pregnancy"}, {"id": "E", "text": "Polyhydramnios"}, {"id": "F", "text": "Oligohydramnios"}]}'::jsonb,
 '{"answers": ["A", "B", "D", "E"], "feedback": {"A": "Correct. Maternal hyperglycaemia drives fetal insulin secretion and accelerated growth.", "B": "Correct. If the pregnancy is further advanced than recorded, the fundal height is correct and the dates are wrong.", "C": "Incorrect. Growth restriction reduces the fundal height rather than increasing it.", "D": "Correct. Two or more fetuses increase uterine size well beyond the expected measurement.", "E": "Correct. Excess amniotic fluid distends the uterus and raises the fundal height.", "F": "Incorrect. Reduced liquor volume makes the uterus smaller, not larger."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Fundal height', 'Size greater than dates', 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510027', 'SATA', 'At the booking visit the nurse reviews the history of a 39-year-old client in her fourth pregnancy. Which findings should the nurse flag for obstetric review? Select all that apply.',
 'The booking visit is a risk-assessment consultation: its purpose is to decide which clients need care beyond the routine midwifery pathway. Previous preterm birth, a previous caesarean, a raised body mass index and treated chronic hypertension each change the surveillance plan, the place of birth or the medication review. Findings that fall within expected limits are documented but do not trigger referral.',
 '{"options": [{"id": "A", "text": "A blood pressure of 118/72 mmHg"}, {"id": "B", "text": "Chronic hypertension treated with medication"}, {"id": "C", "text": "Mild nausea on waking in the mornings"}, {"id": "D", "text": "A previous baby born at 32 weeks of gestation"}, {"id": "E", "text": "A body mass index of 34 kg/m2"}, {"id": "F", "text": "A previous caesarean birth for breech presentation"}]}'::jsonb,
 '{"answers": ["B", "D", "E", "F"], "feedback": {"A": "Incorrect. This blood pressure is within expected limits and needs only routine recording.", "B": "Correct. Antihypertensive therapy must be reviewed for safety in pregnancy and the client monitored for superimposed pre-eclampsia.", "C": "Incorrect. Morning nausea without weight loss or ketonuria is an expected first-trimester symptom.", "D": "Correct. Previous preterm birth is the strongest predictor of recurrence and changes the surveillance plan.", "E": "Correct. A body mass index above 30 kg/m2 raises the risk of gestational diabetes, pre-eclampsia and thromboembolism.", "F": "Correct. A uterine scar affects the planned mode and place of birth and needs obstetric discussion."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Maternity', 'Multisystem',
 'Booking visit', 'Antenatal risk assessment', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510028', 'SATA', 'A client at 20 weeks of gestation has been prescribed oral ferrous sulfate. Which instructions should the nurse give? Select all that apply.',
 'Non-haem iron is absorbed best in an acidic environment and on a relatively empty stomach, so vitamin C enhances absorption while the tannins in tea and coffee and the calcium in milk and antacids reduce it. Dark stools are an expected and harmless effect and are not a reason to stop treatment, whereas constipation is common and is managed with fluid and fibre. Separating iron from calcium supplements by at least two hours preserves absorption of both.',
 '{"options": [{"id": "A", "text": "Expect the stools to become darker than usual"}, {"id": "B", "text": "Take the iron and the calcium supplement together to reduce the number of doses"}, {"id": "C", "text": "Increase fluid and fibre because constipation is common"}, {"id": "D", "text": "Stop the tablets if the stools turn black"}, {"id": "E", "text": "Take the tablet with orange juice or another source of vitamin C"}, {"id": "F", "text": "Avoid taking the tablet with tea, coffee or milk"}]}'::jsonb,
 '{"answers": ["A", "C", "E", "F"], "feedback": {"A": "Correct. Darkened stools are expected with oral iron and are harmless.", "B": "Incorrect. Calcium competes with iron for absorption; the doses should be separated by at least two hours.", "C": "Correct. Constipation is the commonest reason clients abandon iron, and fluid and fibre prevent it.", "D": "Incorrect. Black stools are expected; stopping treatment leaves the anaemia untreated.", "E": "Correct. Ascorbic acid keeps iron in the absorbable ferrous form and increases uptake.", "F": "Correct. Tannins and calcium bind iron in the gut and markedly reduce absorption."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Maternity', 'Multisystem',
 'Oral iron', 'Administration teaching', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510029', 'SATA', 'A client at 12 weeks of gestation asks which foods she should avoid. Which foods should the nurse advise her to avoid? Select all that apply.',
 'Food advice in pregnancy targets three hazards: listeriosis from unpasteurised dairy products, mould-ripened cheeses and pates; salmonella and toxoplasma from raw or undercooked animal products; and methylmercury from large predatory fish, which is toxic to the developing nervous system. Pasteurised and thoroughly cooked foods carry none of these risks and remain important sources of protein, calcium and folate. Blanket avoidance of whole food groups is unnecessary and worsens nutrition.',
 '{"options": [{"id": "A", "text": "Pate and undercooked meat"}, {"id": "B", "text": "Shark, swordfish and marlin"}, {"id": "C", "text": "Pasteurised yoghurt"}, {"id": "D", "text": "Raw or lightly cooked eggs from an uncertified source"}, {"id": "E", "text": "Cooked green leafy vegetables"}, {"id": "F", "text": "Unpasteurised milk and soft mould-ripened cheese"}]}'::jsonb,
 '{"answers": ["A", "B", "D", "F"], "feedback": {"A": "Correct. Pate and undercooked meat carry listeria and toxoplasma.", "B": "Correct. These large predatory fish accumulate methylmercury, which is toxic to the fetal nervous system.", "C": "Incorrect. Pasteurised yoghurt is safe and is a useful source of calcium and protein.", "D": "Correct. Raw or lightly cooked uncertified eggs may carry salmonella.", "E": "Incorrect. Cooked leafy vegetables are safe and are a valuable source of folate and iron.", "F": "Correct. These are classic sources of listeria, which can cross the placenta and cause fetal loss."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Maternity', 'Multisystem',
 'Food safety in pregnancy', 'Foods to avoid', 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510030', 'SATA', 'A client at 14 weeks of gestation keeps two cats and grows vegetables at home. Which measures should the nurse teach to reduce the risk of toxoplasmosis? Select all that apply.',
 'Toxoplasma gondii is acquired from oocysts in cat faeces and soil and from cysts in undercooked meat, and primary infection in pregnancy can cause fetal chorioretinitis, hydrocephalus and intracranial calcification. Practical precautions are to delegate litter tray emptying, wear gloves for gardening, wash produce and cook meat thoroughly. Rehoming the cat and avoiding all contact are unnecessary, because the parasite is transmitted through faeces and soil rather than through stroking the animal.',
 '{"options": [{"id": "A", "text": "Ask another member of the household to empty the cat litter tray"}, {"id": "B", "text": "Wear gloves when gardening and wash the hands afterwards"}, {"id": "C", "text": "Wash all fruit and vegetables thoroughly before eating"}, {"id": "D", "text": "Rehome the cats for the duration of the pregnancy"}, {"id": "E", "text": "Cook all meat until it is no longer pink"}, {"id": "F", "text": "Avoid stroking the cats at any time"}]}'::jsonb,
 '{"answers": ["A", "B", "C", "E"], "feedback": {"A": "Correct. Oocysts are shed in cat faeces and become infective in the tray, so someone else should empty it.", "B": "Correct. Soil can be contaminated with oocysts, so gloves and handwashing are the practical protection.", "C": "Correct. Washing removes soil-borne oocysts from produce.", "D": "Incorrect. Rehoming is unnecessary and causes avoidable distress; hygiene measures are sufficient.", "E": "Correct. Thorough cooking destroys tissue cysts in meat, a major route of infection.", "F": "Incorrect. Transmission is through faeces and soil, not through stroking the cat."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Maternity', 'Multisystem',
 'Toxoplasmosis', 'Prevention in pregnancy', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_SATA_510031', 'SATA', 'A client at 24 weeks of gestation reports constipation. Which self-care measures should the nurse recommend? Select all that apply.',
 'Progesterone slows intestinal transit and the growing uterus compresses the bowel, so constipation is common and is compounded by oral iron. Fibre, fluid and gentle exercise address the mechanism and are recommended first. Liquid paraffin interferes with absorption of the fat-soluble vitamins, and daily stimulant laxatives can provoke uterine irritability, so neither is first-line self-care.',
 '{"options": [{"id": "A", "text": "Use a stimulant laxative every day"}, {"id": "B", "text": "Increase dietary fibre such as fruit, vegetables and wholegrain cereals"}, {"id": "C", "text": "Drink at least eight glasses of water each day"}, {"id": "D", "text": "Take regular gentle exercise such as walking"}, {"id": "E", "text": "Take liquid paraffin each night"}]}'::jsonb,
 '{"answers": ["B", "C", "D"], "feedback": {"A": "Incorrect. Daily stimulant laxatives may cause cramping and uterine irritability and are not first-line.", "B": "Correct. Fibre increases stool bulk and shortens transit time.", "C": "Correct. Adequate fluid keeps the stool soft and is essential for fibre to work.", "D": "Correct. Walking stimulates peristalsis and is safe throughout an uncomplicated pregnancy.", "E": "Incorrect. Liquid paraffin reduces absorption of fat-soluble vitamins and is avoided in pregnancy."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Constipation in pregnancy', 'Self-care measures', 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510032', 'SATA', 'A client at 33 weeks of gestation has varicose veins in both legs. Which measures should the nurse advise? Select all that apply.',
 'Venous return from the legs is reduced in pregnancy by progesterone-mediated vein dilatation and by pressure from the gravid uterus on the pelvic veins. Graduated compression applied before the legs become dependent, frequent elevation, avoiding prolonged standing and resting in the left lateral position all improve venous drainage. Anything that constricts a single point on the limb, such as crossing the legs or wearing garters, does the opposite.',
 '{"options": [{"id": "A", "text": "Wear knee-high elastic bands or garters"}, {"id": "B", "text": "Rest in the left lateral position"}, {"id": "C", "text": "Put on graduated support stockings before getting out of bed"}, {"id": "D", "text": "Rest with the legs elevated several times a day"}, {"id": "E", "text": "Avoid standing still for long periods"}, {"id": "F", "text": "Cross the legs at the knee when sitting to support the veins"}]}'::jsonb,
 '{"answers": ["B", "C", "D", "E"], "feedback": {"A": "Incorrect. Garters constrict at a single level and obstruct rather than assist venous return.", "B": "Correct. The left lateral position lifts the uterus off the inferior vena cava and improves drainage.", "C": "Correct. Applying compression before the legs become dependent prevents the veins filling.", "D": "Correct. Elevation uses gravity to assist venous return and reduces aching.", "E": "Correct. Prolonged standing increases venous pooling and pressure in the legs.", "F": "Incorrect. Crossing the legs compresses the popliteal veins and worsens venous stasis."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Varicosities in pregnancy', 'Self-care measures', 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510033', 'SATA', 'The nurse teaches a client at 20 weeks of gestation which symptoms must be reported immediately. Which symptoms should be included? Select all that apply.',
 'Antenatal danger-sign teaching separates symptoms that may signal haemorrhage, infection, pre-eclampsia or fetal compromise from the ordinary discomforts of pregnancy. Bleeding, leaking liquor, severe headache with visual disturbance and reduced fetal movement each require assessment on the same day. Teaching that lists everything as urgent produces unnecessary alarm and, over time, makes clients less likely to report the findings that matter.',
 '{"options": [{"id": "A", "text": "Mild ankle swelling at the end of the day"}, {"id": "B", "text": "A marked reduction in fetal movement"}, {"id": "C", "text": "Occasional heartburn after a large meal"}, {"id": "D", "text": "Vaginal bleeding"}, {"id": "E", "text": "A gush or steady leaking of fluid from the vagina"}, {"id": "F", "text": "A persistent severe headache with blurred vision"}]}'::jsonb,
 '{"answers": ["B", "D", "E", "F"], "feedback": {"A": "Incorrect. Dependent ankle oedema that appears by evening is an expected finding.", "B": "Correct. A change in the pattern of fetal movement may be the only sign of fetal compromise.", "C": "Incorrect. Heartburn after a large meal reflects progesterone-related reflux and is an expected discomfort.", "D": "Correct. Any antepartum bleeding must be assessed to exclude praevia, abruption or infection.", "E": "Correct. Leaking liquor suggests ruptured membranes, with a risk of infection and preterm birth.", "F": "Correct. Severe headache with visual disturbance is a warning feature of pre-eclampsia."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Antenatal danger signs', 'Client teaching', 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510034', 'SATA', 'A client at 35 weeks of gestation with pre-eclampsia reports epigastric pain and nausea. Which laboratory findings would support a diagnosis of HELLP syndrome? Select all that apply.',
 'HELLP syndrome is a severe variant of pre-eclampsia defined by haemolysis, elevated liver enzymes and a low platelet count. Haemolysis shows as fragmented red cells, a raised lactate dehydrogenase and a low haptoglobin, hepatic distension produces epigastric or right upper quadrant pain with raised transaminases, and platelet consumption drives the count below 100 x 10^9/L. Normal platelets and normal haptoglobin argue against the diagnosis.',
 '{"options": [{"id": "A", "text": "Lactate dehydrogenase 820 units/L"}, {"id": "B", "text": "Haptoglobin within normal limits"}, {"id": "C", "text": "Fragmented red cells on the blood film"}, {"id": "D", "text": "Platelet count 260 x 10^9/L"}, {"id": "E", "text": "Platelet count 82 x 10^9/L"}, {"id": "F", "text": "Aspartate aminotransferase 180 units/L"}]}'::jsonb,
 '{"answers": ["A", "C", "E", "F"], "feedback": {"A": "Correct. A raised lactate dehydrogenase reflects haemolysis and tissue injury.", "B": "Incorrect. Haptoglobin is consumed during haemolysis, so a normal level argues against HELLP.", "C": "Correct. Schistocytes on the film are direct evidence of microangiopathic haemolysis.", "D": "Incorrect. This platelet count is normal and does not support the diagnosis.", "E": "Correct. A platelet count below 100 x 10^9/L is one of the three defining features.", "F": "Correct. A raised transaminase reflects the hepatic involvement in the syndrome."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Multisystem',
 'HELLP syndrome', 'Laboratory findings', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510035', 'SATA', 'A client at 33 weeks of gestation with gestational hypertension is being monitored at home. Which instructions should the nurse give? Select all that apply.',
 'Home monitoring depends on the client recognising the features that mark progression from gestational hypertension to pre-eclampsia with severe features: unrelieved headache, visual disturbance and right upper quadrant or epigastric pain. Regular clinic checks of blood pressure and urine protein detect the changes the client cannot feel. Fluid restriction has no place in management, and monthly weighing is far too infrequent to detect the rapid gain that accompanies worsening oedema.',
 '{"options": [{"id": "A", "text": "Report visual disturbance such as flashing lights or blurring"}, {"id": "B", "text": "Report pain under the ribs on the right side"}, {"id": "C", "text": "Weigh yourself once a month"}, {"id": "D", "text": "Attend the twice-weekly blood pressure and urine checks"}, {"id": "E", "text": "Restrict fluids to one litre a day to reduce the swelling"}, {"id": "F", "text": "Report a headache that does not settle with paracetamol"}]}'::jsonb,
 '{"answers": ["A", "B", "D", "F"], "feedback": {"A": "Correct. Visual disturbance reflects cerebral irritability and requires immediate assessment.", "B": "Correct. Right upper quadrant pain suggests hepatic involvement and possible HELLP syndrome.", "C": "Incorrect. Monthly weighing cannot detect the rapid fluid gain that accompanies worsening disease.", "D": "Correct. Serial blood pressure and proteinuria measurement detects progression before symptoms appear.", "E": "Incorrect. Fluid restriction does not reduce pathological oedema and risks reduced placental perfusion.", "F": "Correct. A headache unrelieved by simple analgesia is a warning feature of severe disease."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Multisystem',
 'Gestational hypertension', 'Home monitoring teaching', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510036', 'SATA', 'A client has had suction evacuation of a complete hydatidiform mole. Which points should the nurse include in the discharge teaching? Select all that apply.',
 'After evacuation of a molar pregnancy, serial human chorionic gonadotrophin measurement is the means of detecting persistent trophoblastic disease, so the level is followed until it is normal for a defined period. Reliable contraception is essential during that time, because a new pregnancy raises the hormone level and makes the surveillance uninterpretable; an intrauterine device is avoided until the level is normal because of the risk of perforation and bleeding. Grief for the lost pregnancy is real and support should be offered alongside the physical follow-up.',
 '{"options": [{"id": "A", "text": "Serial human chorionic gonadotrophin levels will be measured until they are normal for a defined period"}, {"id": "B", "text": "Reliable contraception is needed until the follow-up period is complete"}, {"id": "C", "text": "Report any new vaginal bleeding or a persistent cough"}, {"id": "D", "text": "Try to conceive again as soon as the bleeding stops"}, {"id": "E", "text": "An intrauterine device should be fitted straight away for contraception"}, {"id": "F", "text": "Grief and anxiety about this loss are expected, and support is available"}]}'::jsonb,
 '{"answers": ["A", "B", "C", "F"], "feedback": {"A": "Correct. Falling hormone levels are how persistent trophoblastic disease is excluded.", "B": "Correct. A new pregnancy would raise the hormone level and make surveillance uninterpretable.", "C": "Correct. New bleeding or a persistent cough may indicate persistent or metastatic disease.", "D": "Incorrect. Conception is deferred until follow-up is complete, usually six to twelve months.", "E": "Incorrect. An intrauterine device is avoided until the hormone level is normal because of the risk of perforation and bleeding.", "F": "Correct. This is a pregnancy loss as well as a diagnosis, and emotional support is part of care."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Hydatidiform mole', 'Follow-up teaching', 'Very hard', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510037', 'SATA', 'The nurse teaches a client at 28 weeks of gestation about monitoring fetal movement. Which statements should the nurse include? Select all that apply.',
 'Fetal movement is the client''s own continuous monitor of fetal wellbeing, and a change in the established pattern, rather than an absolute number, is what matters. Counting is best done lying on the left side at a time when the baby is usually active, and reduced movement is reported the same day so that cardiotocography can be arranged. The belief that babies move less towards term is a dangerous myth that delays presentation.',
 '{"options": [{"id": "A", "text": "If no movement is felt for two hours, wait 24 hours before contacting anyone"}, {"id": "B", "text": "Choose a time when the baby is usually active and lie on the left side to count"}, {"id": "C", "text": "Contact the maternity unit the same day if the pattern of movement decreases"}, {"id": "D", "text": "Movements are usually first felt between 16 and 20 weeks in a first pregnancy"}, {"id": "E", "text": "Movements normally decrease in the last weeks because the baby has less room"}, {"id": "F", "text": "Having a cold drink or something to eat before counting is reasonable"}]}'::jsonb,
 '{"answers": ["B", "C", "D", "F"], "feedback": {"A": "Incorrect. Waiting 24 hours after absent movement delays assessment when time matters.", "B": "Correct. Left lateral positioning and a habitually active time make the count reliable.", "C": "Correct. Reduced movement requires same-day assessment, not a wait-and-see approach.", "D": "Correct. Quickening is usually felt between 16 and 20 weeks, later in a first pregnancy.", "E": "Incorrect. Movements change in character but should not reduce in frequency towards term.", "F": "Correct. A cold drink or a snack is a harmless way to prompt activity before counting."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Fetal movement counting', 'Client teaching', 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510038', 'SATA', 'During a routine antenatal visit a client discloses that her partner checks her telephone, controls all the household money and pushed her against a wall last week. Which nursing actions are appropriate? Select all that apply.',
 'Intimate partner violence often begins or escalates in pregnancy and is associated with abruption, preterm birth and low birth weight. The immediate nursing responsibilities are to see the client alone, assess for injury including to the abdomen, document the disclosure accurately in the client''s own words and offer information about support services and safety planning. Confronting the partner or demanding that the client leave removes her control of the situation and can increase the danger to her.',
 '{"options": [{"id": "A", "text": "Raise the incident directly with the partner at the next visit"}, {"id": "B", "text": "Assess the client for injuries, including to the abdomen"}, {"id": "C", "text": "See the client alone, without her partner or family present"}, {"id": "D", "text": "Document the disclosure and any injuries accurately in the record"}, {"id": "E", "text": "Discuss a safety plan and give contact details for local support services"}, {"id": "F", "text": "Tell the client she must leave the relationship before the birth"}]}'::jsonb,
 '{"answers": ["B", "C", "D", "E"], "feedback": {"A": "Incorrect. Confronting the partner breaches confidentiality and can place the client in immediate danger.", "B": "Correct. Abdominal trauma in pregnancy risks abruption, so assessment for injury is essential.", "C": "Correct. Disclosure and assessment are only safe when the client is seen alone.", "D": "Correct. Accurate contemporaneous documentation supports both continuing care and any later legal process.", "E": "Correct. Safety planning and service information give the client usable options without pressure.", "F": "Incorrect. Directing the client to leave removes her control and may increase the risk of serious harm."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Maternity', 'Multisystem',
 'Intimate partner violence', 'Disclosure in pregnancy', 'Hard', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SATA_510039', 'SATA', 'A client at 26 weeks of gestation who has had two previous second-trimester losses tells the nurse that she does not want to buy anything for the baby yet. Which nursing responses are appropriate? Select all that apply.',
 'Delaying preparation is a recognised protective strategy in a pregnancy that follows loss, and attachment often develops only once the pregnancy passes the gestation at which the earlier losses occurred. Acknowledging the strategy, exploring what would increase the client''s sense of safety, offering peer support and building in regular opportunities to voice anxiety respect the client pace. Pressure to prepare, or warnings that worry harms the baby, add guilt to grief.',
 '{"options": [{"id": "A", "text": "Offer information about a pregnancy-after-loss support group"}, {"id": "B", "text": "Insist that she prepares the nursery to encourage bonding"}, {"id": "C", "text": "Arrange time at each visit to discuss her anxieties with the midwife"}, {"id": "D", "text": "Acknowledge that delaying preparation is a common way of coping after a loss"}, {"id": "E", "text": "Ask what would help her feel more confident as the pregnancy continues"}, {"id": "F", "text": "Tell the client that worrying will harm the baby"}]}'::jsonb,
 '{"answers": ["A", "C", "D", "E"], "feedback": {"A": "Correct. Peer support from others who have had a loss reduces isolation.", "B": "Incorrect. Insistence overrides the client''s coping strategy and damages the therapeutic relationship.", "C": "Correct. Predictable time to voice anxiety allows distress to be assessed as the pregnancy progresses.", "D": "Correct. Naming the behaviour as a normal protective response reduces shame and opens discussion.", "E": "Correct. Asking what would help keeps the client in control of the pace of preparation.", "F": "Incorrect. This adds guilt to an already anxious client and is not supported by evidence."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Maternity', 'Reproductive',
 'Pregnancy after loss', 'Emotional support', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SELN_510040', 'SELECT_N', 'A client is booked for a 75 g oral glucose tolerance test next week. Which 3 instructions should the nurse give?',
 'The oral glucose tolerance test measures how the body handles a fixed glucose load, so the conditions have to be standardised. The client eats normally, including carbohydrate, for the three days before the test, fasts for eight to ten hours beforehand with water allowed, and then stays seated and does not smoke while the samples are taken. Carbohydrate restriction beforehand or activity during the test alters glucose handling and produces a result that cannot be interpreted.',
 '{"options": [{"id": "A", "text": "Remain seated and do not smoke during the test"}, {"id": "B", "text": "Take a brisk walk between the blood samples"}, {"id": "C", "text": "Take nothing at all by mouth, including water, from 6 pm the day before"}, {"id": "D", "text": "Follow a low-carbohydrate diet for the 3 days before the test"}, {"id": "E", "text": "Fast overnight for 8 to 10 hours, taking water only"}, {"id": "F", "text": "Eat normally, including carbohydrate, for the 3 days before the test"}], "select_count": 3}'::jsonb,
 '{"answers": ["A", "E", "F"], "feedback": {"A": "Correct. Activity and nicotine both alter glucose handling during the test.", "B": "Incorrect. Exercise increases glucose uptake by muscle and invalidates the result.", "C": "Incorrect. Water is permitted and withholding it risks dehydration without improving the test.", "D": "Incorrect. Carbohydrate restriction impairs insulin response and can produce a falsely abnormal result.", "E": "Correct. A standardised overnight fast with water allowed is required for the fasting sample.", "F": "Correct. Normal carbohydrate intake beforehand prevents a falsely abnormal result."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Multisystem',
 'Gestational diabetes', 'Glucose tolerance test preparation', 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_SELN_510041', 'SELECT_N', 'A client at 33 weeks of gestation with pre-eclampsia has been admitted for observation. Which 3 findings should the nurse report to the obstetric team immediately?',
 'Severe features of pre-eclampsia include a systolic pressure of 160 mmHg or a diastolic of 110 mmHg or more, renal impairment shown by oliguria of less than 30 mL an hour, and neurological irritability shown by hyperreflexia with clonus. Each indicates that the disease has progressed and that magnesium sulfate and a decision about birth are likely to be needed. Trace oedema and a haemoglobin within the expected range do not change management.',
 '{"options": [{"id": "A", "text": "Urine output of 60 mL over the past 3 hours"}, {"id": "B", "text": "Brisk deep tendon reflexes with three beats of clonus"}, {"id": "C", "text": "Trace ankle oedema"}, {"id": "D", "text": "Haemoglobin 11.2 g/dL"}, {"id": "E", "text": "Blood pressure 138/86 mmHg"}, {"id": "F", "text": "Blood pressure 168/112 mmHg"}], "select_count": 3}'::jsonb,
 '{"answers": ["A", "B", "F"], "feedback": {"A": "Correct. This is 20 mL an hour, below the 30 mL an hour threshold, and indicates renal involvement.", "B": "Correct. Hyperreflexia with clonus signals cerebral irritability and impending eclampsia.", "C": "Incorrect. Trace dependent oedema is common in late pregnancy and is not a severe feature.", "D": "Incorrect. This haemoglobin is within the expected range for the third trimester.", "E": "Incorrect. This blood pressure is raised but well below the threshold for severe hypertension.", "F": "Correct. This meets the threshold for severe hypertension and requires urgent treatment."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Multisystem',
 'Pre-eclampsia', 'Severe features', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SELN_510042', 'SELECT_N', 'A client with 6 weeks of amenorrhoea and a positive pregnancy test attends the emergency department. Which 3 findings most strongly suggest an ectopic pregnancy?',
 'An ectopic pregnancy classically presents with amenorrhoea, unilateral lower abdominal pain and scanty dark vaginal bleeding, and cervical motion tenderness is found when the peritoneum is irritated. The bleeding is characteristically light and dark because it is decidual shedding from the uterus rather than loss from the implantation site. Heavy bright red bleeding, a uterus larger than dates and severe vomiting point instead to miscarriage, molar pregnancy and hyperemesis gravidarum.',
 '{"options": [{"id": "A", "text": "Unilateral lower abdominal pain"}, {"id": "B", "text": "Scanty dark vaginal spotting"}, {"id": "C", "text": "Cervical motion tenderness on examination"}, {"id": "D", "text": "Painless heavy bright red bleeding with clots"}, {"id": "E", "text": "A uterus larger than expected for the dates"}, {"id": "F", "text": "Severe vomiting with 4 kg of weight loss"}], "select_count": 3}'::jsonb,
 '{"answers": ["A", "B", "C"], "feedback": {"A": "Correct. Pain localised to one side reflects distension of the affected tube.", "B": "Correct. Light dark bleeding is decidual shedding and is typical of ectopic pregnancy.", "C": "Correct. Pain on moving the cervix indicates peritoneal irritation from blood in the pelvis.", "D": "Incorrect. Heavy bright red loss with clots suggests miscarriage rather than an ectopic pregnancy.", "E": "Incorrect. A uterus larger than dates with very high hormone levels suggests a molar pregnancy.", "F": "Incorrect. Severe vomiting with weight loss describes hyperemesis gravidarum."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Ectopic pregnancy', 'Presenting features', 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SELN_510043', 'SELECT_N', 'A client at 11 weeks of gestation is admitted with hyperemesis gravidarum. She has lost 6 per cent of her booking weight and has 3+ ketones in her urine. Which 3 actions should the nurse expect to carry out?',
 'Hyperemesis gravidarum causes dehydration, hypokalaemia and ketosis, so treatment begins with intravenous rehydration with added potassium and thiamine, an antiemetic given regularly rather than on request, and a period of rest for the stomach before small amounts of oral fluid are reintroduced. Progress is judged by daily weight, urine ketones and electrolytes. Large or fatty meals and oral iron both aggravate nausea and are deferred until the vomiting has settled.',
 '{"options": [{"id": "A", "text": "Give the oral iron tablet with the first meal"}, {"id": "B", "text": "Commence the prescribed intravenous fluid with added potassium"}, {"id": "C", "text": "Give the prescribed antiemetic before oral intake is reintroduced"}, {"id": "D", "text": "Keep the client nil by mouth initially, then reintroduce small amounts of oral fluid"}, {"id": "E", "text": "Encourage a large high-fat meal as soon as the infusion is running"}, {"id": "F", "text": "Weigh the client once a week"}], "select_count": 3}'::jsonb,
 '{"answers": ["B", "C", "D"], "feedback": {"A": "Incorrect. Oral iron is a gastric irritant and is deferred until the vomiting has settled.", "B": "Correct. Rehydration with potassium replacement corrects the dehydration and hypokalaemia.", "C": "Correct. Regular antiemetic cover before oral intake gives reintroduction the best chance of succeeding.", "D": "Correct. A period of gastric rest followed by graded oral fluid is the standard approach.", "E": "Incorrect. Fat delays gastric emptying and a large meal will provoke further vomiting.", "F": "Incorrect. Weight is measured daily in hyperemesis because it is the main marker of progress."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Maternity', 'Multisystem',
 'Hyperemesis gravidarum', 'Inpatient management', 'Hard', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_SELN_510044', 'SELECT_N', 'The nurse reviews the antenatal records of several clients. Which 3 clients should receive anti-D immunoglobulin?',
 'Anti-D immunoglobulin prevents an Rh-negative client who is not yet sensitised from forming antibodies after exposure to Rh-positive fetal cells. It is given as routine prophylaxis at 28 weeks and after any potentially sensitising event, such as amniocentesis, antepartum bleeding, abdominal trauma, external cephalic version or birth of an Rh-positive baby. It has no purpose for an Rh-positive client, and it cannot help a client who already has anti-D antibodies, because sensitisation has already occurred.',
 '{"options": [{"id": "A", "text": "An Rh-negative client who is already sensitised, with anti-D antibodies detected"}, {"id": "B", "text": "An Rh-positive client who has had a fall at 30 weeks of gestation"}, {"id": "C", "text": "An Rh-negative client at 28 weeks of gestation attending for routine prophylaxis"}, {"id": "D", "text": "An Rh-negative client who had an amniocentesis yesterday at 17 weeks"}, {"id": "E", "text": "An Rh-negative client with vaginal bleeding at 14 weeks of gestation"}, {"id": "F", "text": "An Rh-positive client who has just given birth to an Rh-negative baby"}], "select_count": 3}'::jsonb,
 '{"answers": ["C", "D", "E"], "feedback": {"A": "Incorrect. Once anti-D antibodies are present the client is sensitised and immunoglobulin cannot reverse it.", "B": "Incorrect. Trauma is a sensitising event only in a client who is Rh negative.", "C": "Correct. Routine antenatal prophylaxis at 28 weeks covers silent fetomaternal transfusion in the third trimester.", "D": "Correct. Amniocentesis is a potentially sensitising event and requires anti-D within 72 hours.", "E": "Correct. Antepartum bleeding in an Rh-negative client is a sensitising event.", "F": "Incorrect. An Rh-positive client cannot be sensitised to the Rh D antigen."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Maternity', 'Reproductive',
 'Rh alloimmunisation', 'Anti-D indications', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MAT_510045', 'MATRIX', 'A client attends the clinic believing she is pregnant. For each finding, indicate whether it is a presumptive, a probable or a positive sign of pregnancy.',
 'Presumptive signs are the changes the client herself notices and that many other conditions can also cause. Probable signs are those the examiner can detect or measure, but which can still be produced by something else, such as a hormone-secreting tumour or a fibroid. Only findings that come directly from the fetus, detected by the examiner rather than the client, are positive signs: an audible fetal heart, fetal parts visualised on ultrasound and fetal movement felt by the examiner.',
 '{"rows": [{"id": "r1", "text": "Amenorrhoea"}, {"id": "r2", "text": "Goodell sign, softening of the cervix"}, {"id": "r3", "text": "Fetal heart sounds heard with a Doppler device"}, {"id": "r4", "text": "Positive urine pregnancy test"}, {"id": "r5", "text": "Nausea and vomiting on waking"}, {"id": "r6", "text": "Fetal parts visualised on ultrasound"}, {"id": "r7", "text": "Chadwick sign, bluish discolouration of the vagina"}], "columns": [{"id": "c1", "text": "Presumptive"}, {"id": "c2", "text": "Probable"}, {"id": "c3", "text": "Positive"}], "row_label": "Finding"}'::jsonb,
 '{"cells": {"r1": "c1", "r2": "c2", "r3": "c3", "r4": "c2", "r5": "c1", "r6": "c3", "r7": "c2"}, "feedback": {}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Signs of pregnancy', 'Presumptive, probable and positive', 'Medium', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MAT_510046', 'MATRIX', 'For each report from a client, indicate whether it describes an expected discomfort of pregnancy or a finding that must be reported immediately.',
 'Sorting the ordinary from the dangerous is the core skill of antenatal client teaching. Nasal stuffiness, reflux and irregular painless tightenings are consequences of the hormonal and mechanical changes of pregnancy and need self-care advice only. Severe headache with visual disturbance, urinary symptoms with back pain and leaking liquor point respectively to pre-eclampsia, pyelonephritis and ruptured membranes, and each needs assessment the same day.',
 '{"rows": [{"id": "r1", "text": "Nasal stuffiness and an occasional nosebleed at 22 weeks"}, {"id": "r2", "text": "Sudden severe headache with blurred vision at 34 weeks"}, {"id": "r3", "text": "Heartburn after meals at 30 weeks"}, {"id": "r4", "text": "Burning on passing urine with low back pain at 18 weeks"}, {"id": "r5", "text": "Irregular painless tightenings that stop on walking at 32 weeks"}, {"id": "r6", "text": "Clear fluid leaking from the vagina at 30 weeks"}], "columns": [{"id": "c1", "text": "Expected discomfort"}, {"id": "c2", "text": "Report immediately"}], "row_label": "Client report"}'::jsonb,
 '{"cells": {"r1": "c1", "r2": "c2", "r3": "c1", "r4": "c2", "r5": "c1", "r6": "c2"}, "feedback": {}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Antenatal discomforts', 'Expected finding or danger sign', 'Easy', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MAT_510047', 'MATRIX', 'For each clinical feature, indicate whether it is characteristic of placenta praevia or of abruptio placentae.',
 'Placenta praevia bleeds because a placenta implanted over or near the cervical os is sheared as the lower segment forms, so the loss is bright red, painless and revealed, and the uterus stays soft. Abruptio placentae bleeds because the placenta separates from the uterine wall, so blood tracks into the myometrium producing constant pain and a rigid tender uterus, and much of the loss may be concealed. A high or malpresenting presenting part is characteristic of praevia because the placenta occupies the lower segment.',
 '{"rows": [{"id": "r1", "text": "Painless bright red bleeding"}, {"id": "r2", "text": "Dark red bleeding with constant abdominal pain"}, {"id": "r3", "text": "Soft, non-tender uterus"}, {"id": "r4", "text": "Rigid, board-like tender uterus"}, {"id": "r5", "text": "Blood loss may be concealed behind the placenta"}, {"id": "r6", "text": "High presenting part or malpresentation is common"}], "columns": [{"id": "c1", "text": "Placenta praevia"}, {"id": "c2", "text": "Abruptio placentae"}], "row_label": "Clinical feature"}'::jsonb,
 '{"cells": {"r1": "c1", "r2": "c2", "r3": "c1", "r4": "c2", "r5": "c2", "r6": "c1"}, "feedback": {}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Antepartum haemorrhage', 'Praevia compared with abruption', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MAT_510048', 'MATRIX', 'A client attends for a routine visit at 34 weeks of gestation. For each finding, indicate whether it is expected or unexpected at this gestation.',
 'Routine antenatal surveillance works by comparing each measurement against the value expected for the gestation. A fundal height within about 2 cm of the number of weeks, a steady weekly gain of roughly 0.4 kg, a haemoglobin above 11 g/dL and a fetal heart rate between 110 and 160 beats per minute are all expected. A blood pressure of 152/98 mmHg and 3+ proteinuria are not, and together they suggest pre-eclampsia requiring same-day review.',
 '{"rows": [{"id": "r1", "text": "Symphysis-fundal height 33 cm"}, {"id": "r2", "text": "Blood pressure 152/98 mmHg"}, {"id": "r3", "text": "Weight gain of 0.4 kg since last week"}, {"id": "r4", "text": "Haemoglobin 11.4 g/dL"}, {"id": "r5", "text": "Fetal heart rate 142 beats per minute"}, {"id": "r6", "text": "Urinalysis showing 3+ protein"}, {"id": "r7", "text": "Ankle oedema that is absent in the morning"}], "columns": [{"id": "c1", "text": "Expected"}, {"id": "c2", "text": "Unexpected"}], "row_label": "Finding"}'::jsonb,
 '{"cells": {"r1": "c1", "r2": "c2", "r3": "c1", "r4": "c1", "r5": "c1", "r6": "c2", "r7": "c1"}, "feedback": {}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Routine antenatal visit', 'Expected and unexpected findings', 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MMR_510049', 'MATRIX_MR', 'A client at 16 weeks of gestation is having an amniocentesis. For each nursing action, indicate when it applies. Select all columns that apply to each row.',
 'Amniocentesis is a sterile ultrasound-guided procedure, so the nurse confirms informed consent and asks the client to empty her bladder beforehand, maintains the sterile field during the procedure, and observes afterwards for the complications that matter: leaking liquor, bleeding and contractions. The fetal heart rate is checked before, during and after, because it is the measure that detects fetal compromise at any stage. An Rh-negative client receives anti-D immunoglobulin afterwards, because the procedure is a sensitising event.',
 '{"rows": [{"id": "r1", "text": "Confirm that written informed consent has been obtained"}, {"id": "r2", "text": "Ask the client to empty her bladder"}, {"id": "r3", "text": "Maintain the sterile field while the sample is taken"}, {"id": "r4", "text": "Check the fetal heart rate"}, {"id": "r5", "text": "Observe for leaking fluid, bleeding or contractions and teach the client to report them"}, {"id": "r6", "text": "Administer anti-D immunoglobulin to an Rh-negative client"}], "columns": [{"id": "c1", "text": "Before the procedure"}, {"id": "c2", "text": "During the procedure"}, {"id": "c3", "text": "After the procedure"}], "row_label": "Nursing action"}'::jsonb,
 '{"cells": {"r1": ["c1"], "r2": ["c1"], "r3": ["c2"], "r4": ["c1", "c2", "c3"], "r5": ["c3"], "r6": ["c3"]}, "feedback": {}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Maternity', 'Reproductive',
 'Amniocentesis', 'Nursing care by procedure phase', 'Very hard', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_MMR_510050', 'MATRIX_MR', 'For each vaccine, indicate how it is regarded in pregnancy. Select all columns that apply to each row.',
 'Inactivated vaccines are safe in pregnancy because they cannot replicate, and two of them, inactivated influenza vaccine and the pertussis-containing Tdap vaccine, are recommended for every pregnancy: influenza protects the client from severe illness, and Tdap given in the third trimester transfers antibody that protects the newborn before the primary course begins. Other inactivated vaccines, such as hepatitis B, are safe and given when the client has a specific indication. Live attenuated vaccines, including measles, mumps and rubella and varicella, are contraindicated because of the theoretical risk to the fetus and are deferred until after birth.',
 '{"rows": [{"id": "r1", "text": "Inactivated influenza vaccine"}, {"id": "r2", "text": "Tetanus, diphtheria and acellular pertussis vaccine"}, {"id": "r3", "text": "Measles, mumps and rubella vaccine"}, {"id": "r4", "text": "Varicella vaccine"}, {"id": "r5", "text": "Hepatitis B vaccine for a client at occupational risk"}], "columns": [{"id": "c1", "text": "Safe in pregnancy"}, {"id": "c2", "text": "Recommended for every pregnancy"}, {"id": "c3", "text": "Contraindicated in pregnancy"}], "row_label": "Vaccine"}'::jsonb,
 '{"cells": {"r1": ["c1", "c2"], "r2": ["c1", "c2"], "r3": ["c3"], "r4": ["c3"], "r5": ["c1"]}, "feedback": {}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Maternity', 'Multisystem',
 'Immunisation in pregnancy', 'Safe and contraindicated vaccines', 'Medium', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MMR_510051', 'MATRIX_MR', 'For each antenatal test, indicate what it is used for and whether it is invasive. Select all columns that apply to each row.',
 'Tests of current fetal wellbeing, such as the non-stress test and the biophysical profile, describe how the fetus is coping now and are non-invasive. Tests for fetal anomaly identify a structural or chromosomal problem: first-trimester combined screening estimates risk without entering the uterus, whereas amniocentesis and chorionic villus sampling give a diagnosis but require a needle or catheter and carry a small risk of pregnancy loss. Distinguishing a screening test from a diagnostic one is central to the counselling the nurse gives before consent.',
 '{"rows": [{"id": "r1", "text": "Non-stress test"}, {"id": "r2", "text": "Amniocentesis"}, {"id": "r3", "text": "Biophysical profile"}, {"id": "r4", "text": "Chorionic villus sampling"}, {"id": "r5", "text": "First-trimester combined screening"}], "columns": [{"id": "c1", "text": "Assesses fetal anomaly risk or diagnosis"}, {"id": "c2", "text": "Assesses current fetal wellbeing"}, {"id": "c3", "text": "Invasive, with a risk of pregnancy loss"}], "row_label": "Test"}'::jsonb,
 '{"cells": {"r1": ["c2"], "r2": ["c1", "c3"], "r3": ["c2"], "r4": ["c1", "c3"], "r5": ["c1"]}, "feedback": {}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive',
 'Antenatal screening and diagnosis', 'Purpose and invasiveness', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_CLZ_510052', 'CLOZE', 'The nurse explains the routine antenatal visit schedule to a client with an uncomplicated pregnancy. Visits are usually arranged every {1} until 28 weeks of gestation, every {2} from 28 to 36 weeks, and {3} from 36 weeks until the birth.',
 'The routine schedule concentrates contacts in the period when complications are most likely to appear and to change management. Monthly visits are sufficient while the main tasks are dating, screening and health promotion; fortnightly visits from 28 weeks allow detection of pre-eclampsia and growth restriction; weekly visits from 36 weeks monitor presentation, growth and the onset of labour. Any complication, such as hypertension, diabetes or reduced growth, increases the frequency regardless of gestation.',
 '{"blanks": [{"id": "b1", "choices": [{"id": "c1", "text": "4 weeks"}, {"id": "c2", "text": "2 weeks"}, {"id": "c3", "text": "6 weeks"}]}, {"id": "b2", "choices": [{"id": "c1", "text": "4 weeks"}, {"id": "c2", "text": "2 weeks"}, {"id": "c3", "text": "6 weeks"}]}, {"id": "b3", "choices": [{"id": "c1", "text": "every 4 weeks"}, {"id": "c2", "text": "every 2 weeks"}, {"id": "c3", "text": "weekly"}]}]}'::jsonb,
 '{"answers": {"b1": "c1", "b2": "c2", "b3": "c3"}, "feedback": {}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Antenatal visit schedule', 'Routine visit intervals', 'Easy', 'CURATOR_LABEL', 'Remember', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_CLZ_510053', 'CLOZE', 'An Rh-negative client with no anti-D antibodies is counselled about anti-D immunoglobulin. Routine antenatal prophylaxis is given at {1} of gestation, and after the birth of an Rh-positive baby a dose must be given within {2}.',
 'Routine antenatal prophylaxis at 28 weeks covers the silent passage of fetal cells across the placenta during the third trimester, when most sensitisation occurs. After birth, the cord blood group is checked and, if the baby is Rh positive, a further dose is given within 72 hours, because immunoglobulin can only prevent an antibody response that has not yet been established. A Kleihauer test quantifies the size of the fetomaternal bleed so that an additional dose can be given when the bleed is large.',
 '{"blanks": [{"id": "b1", "choices": [{"id": "c1", "text": "20 weeks"}, {"id": "c2", "text": "28 weeks"}, {"id": "c3", "text": "36 weeks"}]}, {"id": "b2", "choices": [{"id": "c1", "text": "24 hours"}, {"id": "c2", "text": "72 hours"}, {"id": "c3", "text": "7 days"}]}]}'::jsonb,
 '{"answers": {"b1": "c2", "b2": "c2"}, "feedback": {}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Maternity', 'Reproductive',
 'Rh alloimmunisation', 'Anti-D timing', 'Medium', 'CURATOR_LABEL', 'Remember', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_TF_510054', 'TF', 'At 20 weeks of gestation the fundus is normally palpable at the level of the umbilicus. Is this statement true or false?',
 'The uterus is a pelvic organ until about 12 weeks, when the fundus becomes palpable just above the symphysis pubis; it reaches the umbilicus at about 20 weeks and the xiphisternum at about 36 weeks, dropping again when the presenting part engages. These landmarks give the nurse a rapid check on gestation before the tape measure is used. From 24 weeks the measurement in centimetres approximates the gestational age in weeks, within about 2 cm.',
 '{"options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. The fundus reaches the umbilicus at about 20 weeks of gestation.", "B": "Incorrect. The umbilical landmark corresponds to about 20 weeks; 12 weeks corresponds to the symphysis pubis."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive',
 'Fundal height', 'Palpation landmarks', 'Very easy', 'CURATOR_LABEL', 'Remember', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),
('NCLEX_DO_510055', 'DRAG_ORDER', 'Four clients are waiting in a busy antenatal clinic. Place them in the order in which the nurse should assess them, from first to last.',
 'Prioritisation in the antenatal clinic follows the risk of imminent harm rather than the order of arrival. Severe hypertension with a headache carries an immediate risk of eclampsia and stroke, so it is seen first; absent fetal movement may be the only sign of fetal compromise and is second; ongoing vomiting with weight loss threatens hydration and electrolytes but is not immediately life-threatening; and a routine visit with stable findings can wait. Naming the reason for each position matters more than memorising the sequence, because the same logic applies to any waiting list.',
 '{"slots": [{"id": "s1", "target_text": "1st"}, {"id": "s2", "target_text": "2nd"}, {"id": "s3", "target_text": "3rd"}, {"id": "s4", "target_text": "4th"}], "tokens": [{"id": "t1", "text": "A client at 24 weeks attending for a routine visit and a repeat haemoglobin"}, {"id": "t2", "text": "A client at 36 weeks with a blood pressure of 168/110 mmHg and a headache"}, {"id": "t3", "text": "A client at 12 weeks who is still vomiting and has lost 3 kg"}, {"id": "t4", "text": "A client at 30 weeks who has felt no fetal movement since the previous evening"}]}'::jsonb,
 '{"slots": {"s1": "t2", "s2": "t4", "s3": "t3", "s4": "t1"}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Maternity', 'Multisystem',
 'Antenatal clinic prioritisation', 'Order of assessment', 'Very hard', 'CURATOR_LABEL', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');
